const raw = $('OpenAI Generate Post').first().json.output?.[0]?.content?.[0]?.text ?? '';
const cleaned = String(raw).trim().replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```$/i,'').trim();
let data;
try { data = JSON.parse(cleaned); } catch (e) { throw new Error('WorkflowAI Mini: OpenAI returned invalid JSON'); }
const headline = String(data.headline || '').trim();
const postText = String(data.post_text || '').trim();
const imagePrompt = String(data.image_prompt || '').trim();
if (!postText || !imagePrompt) throw new Error('WorkflowAI Mini: post_text or image_prompt is missing');
const source = $('Code for Request Preparation').first().json;
return [{json:{...source, headline, post_text:postText, image_prompt:imagePrompt}}];

const image = $input.first();
const content = $('Code for Content Validation').first().json;
if (!image.binary || !Object.keys(image.binary).length) throw new Error('WorkflowAI Mini: image generator did not return binary image data');
return [{ json: content, binary: image.binary }];

const d = $('Finalize Post and Image').first();
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

let imageHtml = '';
const binaryKeys = Object.keys(d.binary || {});
if (binaryKeys.length) {
  const key = binaryKeys[0];
  const meta = d.binary[key] || {};
  const buffer = await this.helpers.getBinaryDataBuffer(0, key);
  if (buffer?.length) {
    const base64 = buffer.toString('base64');
    imageHtml = `<img src="data:${meta.mimeType || 'image/png'};base64,${base64}" alt="Generated image">`;
  }
}

const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{font-family:Arial,sans-serif;background:#0b1020;color:#eef2ff;margin:0;padding:28px}.wrap{max-width:900px;margin:auto}.card{background:#131b30;border:1px solid #2b3655;border-radius:18px;padding:22px;margin:16px 0}h1{font-size:34px;margin-bottom:8px}h2{font-size:24px}pre{white-space:pre-wrap;font-family:Arial,sans-serif;line-height:1.6;font-size:16px}img{display:block;width:100%;height:auto;border-radius:18px;margin-top:18px}.small{opacity:.72;font-size:13px}.cta{margin-top:18px;padding:14px;border-radius:14px;background:#18233f}.cta b{display:block;margin-bottom:6px}</style></head><body><div class="wrap"><h1>WorkflowAI Mini</h1><p class="small">Free demo workflow for n8n</p><div class="card"><h2>${esc(d.json.headline || 'Generated post')}</h2><pre>${esc(d.json.post_text)}</pre>${imageHtml}</div><div class="cta"><b>Want full automation?</b>WorkflowAI can be extended with Telegram, VK and other digital channels through API integrations. The full WorkflowAI Marketing System adds multi-client profiles, Marketing Brain, recurring 30-day campaigns, queue management, approval and publishing.</div></div></body></html>`;

return [{ json: { ...d.json, html }, binary: d.binary }];
